"""3L.3-S1: reproducible running-gear screening; no production dimensions."""
from pathlib import Path
import math,json,hashlib

ROOT=Path(__file__).resolve().parent
DIST=ROOT.parent.parent
mass_path=ROOT.parent/'brake-selection-l2/calculations/predecessor_mass_basis.json'
mass=json.loads(mass_path.read_text())['configuration']
g=9.80665
inputs={
 'issue':'3L.3-S1','date':'2026-10-19','status':'ENGINEERING SCREEN ONLY; NOT A SELECTED AXLE, BEARING OR GUIDE DESIGN',
 'mass_source':{'path':str(mass_path.relative_to(DIST)),'sha256':hashlib.sha256(mass_path.read_bytes()).hexdigest()},
 'upper_regular_mass_kg':mass['regular_upper_design_case_kg'],'wheels_per_coach':8,
 'shaft_screen':{'diameters_mm':[50.8,60,70,80,90,100],'diameter_status':'Comparison diameters only. 50.8mm audits the unaccepted G1 display value. No candidate is selected.','force_multipliers':[1,2,3],'force_basis':'Allocated upper coach rail load/8 multiplied by trial multiplier, used as a radial journal-force proxy. This is not a calculated journal reaction, design impact factor or bound on uneven loading.','wheel_contact_to_effective_journal_center_offsets_mm':[75,150,225],'offset_status':'Trial lever arms only; actual tire contact, wheel, bearing pressure-center and brake overhang geometry remains open.','torque_trials_Nm':[0,350,1000,2000],'torque_status':'Independent sensitivity values, NOT a maximum brake torque, an OEM rating or a validated fault load. D1 maximum applied torque still required.','model':'Solid uniform round section; bending M=Q*e, sigma=32*M/(pi*d^3); tau=16*T/(pi*d^3); elastic von Mises=sqrt(sigma^2+3*tau^2). Units converted to N,mm,MPa.','excludes':['Notch and fillet stresses','Wheel and bearing press-fit fretting','Reversed bending fatigue','Braking and lateral multi-plane bending','Shaft deflection and bearing alignment','Wheel/hub interference stresses','Actual material, toughness and heat treatment','Uneven/impact/twist loading','Corrosion, wear, inspection interval and reliability targets'],'allowable_stress_MPa':None,'selected_axle_diameter_mm':None},
 'guide_screen':{'bearing_center_span_trials_mm':[1100,1300,1500],'differential_bearing_height_trials_mm':[5,10,20,30],'relative_angle_definition':'Axle tilt relative to the local guide-frame datum. Delta is differential bearing-center height relative to that datum; it is not automatically equal to rail crosslevel or vehicle roll.','trial_box_width_along_axle_mm':100,'trial_box_height_mm':150,'box_status':'Illustrative rectangular-envelope calculation only; not actual box or guide dimensions.','formula':'alpha=atan(Delta/B); extra total transverse width=b*cos(alpha)+h*abs(sin(alpha))-b.','acceptance':'No allowable guide clearance assigned. Do not enlarge guide gaps on this basis without restraint, wear and stability design.'},
 'bearing_screen':{'status':'Documented comparison leads only; neither has been selected or endorsed for this railway. Same boundary dimensions do not establish interchangeability.','equivalent_dynamic_load_trials_per_single_bearing_kN':[20,40,60],'load_status':'Hypothetical equivalent dynamic load P after radial/axial/load-distribution calculation; these values are not inferred directly from coach axle loads.','formula':'L10=(C/P)^(10/3), in million revolutions for roller bearings. Basic 90% fatigue-life model only.','excludes':['Actual tapered-bearing induced axial forces and paired-setting calculations','Load spectrum and modified reliability','Grease/seal contamination, water, washdown and long storage','Minimum load, temperature, clearance/preload and lubrication','Shaft/housing fits, support rigidity, skew and deflection','Brake heat and axle retention','Supplier confirmation of rail application and controlled current drawing'],'selected_bearing':None},
 'engineering_release':False,'fabrication_release':False
}
bearings=[
 {'id':'BE-J01','manufacturer':'JTEKT / Koyo','designation':'30214JR','bearing_type':'Single-row tapered roller','d_mm':70,'D_mm':125,'T_mm':26.25,'inner_ring_width_B_mm':24,'outer_ring_width_C_mm':21,'Cr_kN':173,'C0r_kN':173,'source':'https://koyo.jtekt.co.jp/en/products/detail/?pno=30214JR','source_kind':'Current manufacturer product data','checked':'2026-10-19','inventory':'Listed in manufacturer product catalog; stock, price, lead time and rail suitability unconfirmed'},
 {'id':'BE-S01','manufacturer':'SKF','designation':'30214 J2/Q','bearing_type':'Single-row tapered roller','d_mm':70,'D_mm':125,'T_mm':26.25,'Cr_kN':125,'C0r_kN':156,'source':'https://cdn.skfmediahub.skf.com/api/public/094da9ad401d0567/pdf_preview_medium/094da9ad401d0567_pdf_preview_medium.pdf','source_kind':'SKF Agri solutions, printed p15 / PDF page8; catalog evidence, not exact delivered revision','checked':'2026-10-19','inventory':'Listed in manufacturer catalog; stock, price, lead time and rail suitability unconfirmed'}
]
shaft=[]
qref=mass['regular_upper_design_case_kg']*g/8
for mult in inputs['shaft_screen']['force_multipliers']:
 for e in inputs['shaft_screen']['wheel_contact_to_effective_journal_center_offsets_mm']:
  for d in inputs['shaft_screen']['diameters_mm']:
   for t in inputs['shaft_screen']['torque_trials_Nm']:
    m=qref*mult*e
    sigma=32*m/(math.pi*d**3);tau=16*t*1000/(math.pi*d**3)
    shaft.append({'force_trial_multiplier':mult,'force_proxy_N':qref*mult,'offset_trial_mm':e,'diameter_trial_mm':d,'torque_trial_Nm':t,'moment_trial_Nm':m/1000,'nominal_bending_stress_MPa':sigma,'nominal_torsion_stress_MPa':tau,'nominal_combined_von_mises_MPa':math.sqrt(sigma*sigma+3*tau*tau)})
guide=[]
for b in inputs['guide_screen']['bearing_center_span_trials_mm']:
 for delta in inputs['guide_screen']['differential_bearing_height_trials_mm']:
  a=math.atan(delta/b);w=100;h=150
  guide.append({'span_trial_mm':b,'differential_height_trial_mm':delta,'relative_tilt_degrees':math.degrees(a),'trial_box_transverse_envelope_growth_total_mm':w*math.cos(a)+h*abs(math.sin(a))-w})
life=[]
for b in bearings:
 for p in inputs['bearing_screen']['equivalent_dynamic_load_trials_per_single_bearing_kN']:
  life.append({'bearing_id':b['id'],'equivalent_dynamic_load_trial_kN':p,'basic_L10_million_revolutions':(b['Cr_kN']/p)**(10/3)})
results={'uniform_static_rail_load_reference_N':qref,'shaft_rows':shaft,'guide_rows':guide,'bearing_life_sensitivity':life,'selected_example':{'shaft_rows':[r for r in shaft if r['force_trial_multiplier']==2 and r['offset_trial_mm']==150 and r['torque_trial_Nm']==0],'guide_row':next(r for r in guide if r['span_trial_mm']==1300 and r['differential_height_trial_mm']==20)},'conclusions':['The old 2-inch display axle has no substantiated strength basis. Screening stress changes strongly with both journal lever arm and diameter; do not promote it to a build dimension.','A nominal70mm bearing bore does not prove a70mm shaft or wheel seat is sufficient; journal and larger wheel-seat sections must be designed together.','Axle tilt relative to the guide frame needs an explicit angular-compliance path. A square vertical slide alone cannot be assumed compatible with rigidly aligned bearings and wheelset tilt.','Two same-envelope bearings have different catalog ratings. Do not substitute by boundary dimensions or add two single-bearing ratings to create a fictitious axlebox rating.','Basic bearing life arithmetic does not close rail suitability, actual loads, axlebox stiffness, setting or environmental reliability.']}
interfaces={
 'issue':'3L.3-S1','design_direction':'Retain custom axleboxes and frame as the primary route; define bearing arrangement and guide articulation before spring saddles or brake-reaction joints.',
 'motions':[{'pair':'Axle / bearing inner rings','required':'Rotate together; inner-ring fit and axial retention must be designed.','must_not':'Treat the journal as a stationary semi-trailer spindle.'},{'pair':'Bearing outer rings / axlebox','required':'Nonrotating support with controlled fits, shoulders, seal seats, lubrication and retention.','must_not':'Invent clearance/preload, bore tolerance or end-cap clamp loads.'},{'pair':'Axlebox / bogie frame','required':'Specified vertical travel plus angular compliance for wheelset tilt, controlled longitudinal/lateral restraint and removal retention.','must_not':'Assume long rigid square guides permit tilt without binding.'},{'pair':'D1 brake carrier / axlebox','required':'Spider, cam and chamber support remain aligned to the rotating drum through allowed motions. Brake reaction closes into guide/frame without an incompatible additional constraint.','must_not':'Weld the stationary spider to the rotating axle, or add a rigid torque link that locks suspension motion.'},{'pair':'Bogie / coach','required':'A separately retained body bearing/pivot, prescribed yaw and roll/pitch accommodation, controlled sidebearer law.','must_not':'Use spring travel as a substitute for truck yaw.'}],
 'supplier_return_needed':['Controlled bearing arrangement drawing, exact suffixes, tolerances, fits, shoulder/radius data, setting method and retention; usable bearing CAD if provided.','Rail wheel profile, back-to-back, minimum worn diameter, hub/wheel-seat geometry, material and inspection basis.','Exact delivered D1 drum pilot/bolt circle/mating face/OD/depth and chamber/cam/spider geometry plus full service/spring force-torque curves.'],
 'engineer_definition_needed':['Accepted operational/fault load cases and fatigue spectrum','Whole-truck sprung/unsprung mass and CG','Axle strength/deflection and bearing load distribution','Guide tilt freedom, bush/link/liner design, brake-reaction compatibility and wheel-load response on track twist','Joint materials, tolerances, bolt/weld calculations and prototype acceptance criteria'],
 'not_all_work_blocked':'Supplier-dependent parts remain held; spring/damper functional specification, complete-truck load-case model, electrical/HVAC and other independent program work can continue.'
}
sources=[{'id':'BE-J01','url':bearings[0]['source'],'publisher':'JTEKT','checked':'2026-10-19','use':'Dimensions and ratings for exact30214JR; no material/fit/rail approval transferred.'},{'id':'BE-S01','url':bearings[1]['source'],'publisher':'SKF','checked':'2026-10-19','locator':'Printed15 / PDF8','use':'Comparison dimensions and ratings for30214J2/Q; current delivered revision still required.'},{'id':'BE-LIFE','url':'https://koyo.jtekt.co.jp/en/support/bearing-knowledge/5-2000.html','publisher':'JTEKT','checked':'2026-10-19','use':'Basic roller-bearing rating-life relation and90% reliability meaning.'},{'id':'BE-STATIC','url':'https://koyo.jtekt.co.jp/en/support/bearing-knowledge/5-5000.html','publisher':'JTEKT','checked':'2026-10-19','use':'Static and dynamic load checks are distinct; no static safety factor adopted.'},{'id':'BE-RAIL','url':'https://www.timken.com/products/timken-ap-and-ap-2-integrated-tapered-roller-bearing-assemblies/','publisher':'Timken','checked':'2026-10-19','use':'Rail-specific sealed/preset unit comparison route; no particular size or price selected.'}]
for name,obj in [('running_gear_inputs_S1.json',inputs),('bearing_candidates_S1.json',bearings),('running_gear_results_S1.json',results),('motion_interfaces_S1.json',interfaces),('running_gear_sources_S1.json',sources)]:
 (ROOT/name).write_text(json.dumps(obj,indent=2)+'\n')
assert len(shaft)==216 and len(guide)==12 and len(life)==6
ex=results['selected_example']['shaft_rows']
assert all(abs(r['nominal_bending_stress_MPa']*r['diameter_trial_mm']**3-32*(qref*2*150)/math.pi)<1e-5 for r in ex)
assert abs(qref*8-mass['regular_upper_design_case_kg']*g)<1e-8
assert abs((2**(10/3))*life[1]['basic_L10_million_revolutions']-life[0]['basic_L10_million_revolutions'])<1e-8
validation={'issue':'3L.3-S1','checks':['216 shaft sensitivities','12 relative-tilt cases','6 exact-part bearing-life sensitivities','Uniform rail-load reference recovers allocated coach weight','Inverse-cube bending-stress scaling','Bearing-life load exponent check'],'scope':'Arithmetic and data consistency only; no accepted axle, bearing, guide or release.'}
(ROOT/'running_gear_validation_S1.json').write_text(json.dumps(validation,indent=2)+'\n')
print(json.dumps({'shaft_cases':len(shaft),'tilt_cases':len(guide),'example':results['selected_example']}))
